import { parseHex, toHslString, toRgbString } from "../color.ts";
import {
  cssVarName,
  figmaName,
  isSemanticColor,
  tailwindColorName,
  textStyleName,
} from "../naming.ts";
import type { ResolvedToken, TokenSet, Typography } from "../types.ts";
import { declarations, resolvedCss, type Lookup } from "../values.ts";

const NOTE =
  "<!-- Generated by @cesuain/tokens from packages/tokens/src. Do not edit by hand; run `pnpm tokens:build`. -->\n";

const code = (s: string) => `\`${s.replace(/\|/g, "\\|")}\``;
const row = (cells: string[]) => `| ${cells.join(" | ")} |`;
const table = (head: string[], rows: string[][]) =>
  [row(head), row(head.map(() => "---")), ...rows.map(row)].join("\n");

function lookupFor(set: TokenSet, theme: string): Lookup {
  return new Map([...set.base, ...(set.themed[theme] ?? [])].map((t) => [t.name, t]));
}

function themedValue(set: TokenSet, theme: string, name: string): ResolvedToken | undefined {
  return (set.themed[theme] ?? []).find((t) => t.name === name);
}

export function tokenReferenceMd(set: TokenSet): string {
  const out: string[] = [
    NOTE,
    "# Token reference",
    "",
    `Themes: ${set.themes.map((t) => (t === set.defaultTheme ? `**${t}** (default)` : t)).join(", ")}. ` +
      "Values below are generated from the canonical DTCG sources in `packages/tokens/src`.",
    "",
    "## Semantic colors",
    "",
  ];
  const themed = set.themed[set.defaultTheme] ?? [];
  out.push(
    table(
      ["Token", "CSS variable", ...set.themes.map((t) => `${t} (alias → value)`), "Purpose"],
      themed
        .filter((t) => t.type === "color")
        .map((t) => [
          code(t.name),
          code(cssVarName(t)),
          ...set.themes.map((theme) => {
            const v = themedValue(set, theme, t.name);
            return v
              ? `${v.aliasOf ? `${code(v.aliasOf)} → ` : ""}${code(v.resolved as string)}`
              : "—";
          }),
          t.description ?? "",
        ]),
    ),
    "",
    "## Contrast",
    "",
    "Pairs declared in `src/meta/contrast.json`. The build fails when any pair drops below its minimum.",
    "",
    table(
      ["Usage", "Foreground", "Background", ...set.themes, "Minimum"],
      [...new Set(set.contrast.map((c) => `${c.foreground}|${c.background}|${c.usage}`))].map(
        (key) => {
          const [fg, bg, usage] = key.split("|") as [string, string, string];
          const results = set.contrast.filter(
            (c) => c.foreground === fg && c.background === bg && c.usage === usage,
          );
          return [
            usage,
            code(fg),
            code(bg),
            ...set.themes.map((theme) => {
              const r = results.find((c) => c.theme === theme);
              return r ? `${r.ratio}:1 ${r.pass ? "✅" : "❌"}` : "—";
            }),
            `${results[0]?.minimum}:1`,
          ];
        },
      ),
    ),
    "",
    "## Primitive palette",
    "",
  );
  out.push(
    table(
      ["Token", "CSS variable", "HEX", "RGB", "HSL"],
      set.base
        .filter((t) => t.type === "color")
        .map((t) => {
          const rgba = parseHex(t.resolved as string);
          return [
            code(t.name),
            code(cssVarName(t)),
            code(t.resolved as string),
            code(toRgbString(rgba)),
            code(toHslString(rgba)),
          ];
        }),
    ),
    "",
    "## Typography",
    "",
  );
  const baseLookup = lookupFor(set, set.defaultTheme);
  out.push(
    table(
      ["Style", "Utility", "Family", "Weight", "Size", "Line height", "Tracking", "Usage"],
      set.base
        .filter((t) => t.type === "typography")
        .map((t) => {
          const v = t.resolved as Typography;
          const size = resolvedCss({ type: "dimension", extensions: {} }, v.fontSize);
          const min = t.fluidMin
            ? resolvedCss({ type: "dimension", extensions: {} }, t.fluidMin)
            : null;
          return [
            code(t.name),
            code(`text-${textStyleName(t)}`),
            `${v.fontFamily[0]}${t.extensions.textTransform === "uppercase" ? " (uppercase)" : ""}`,
            String(v.fontWeight),
            min ? `${min} → ${size} (fluid)` : size,
            String(v.lineHeight),
            resolvedCss({ type: "dimension", extensions: {} }, v.letterSpacing),
            t.description ?? "",
          ];
        }),
    ),
    "",
  );

  const section = (title: string, filter: (t: ResolvedToken) => boolean) => {
    const rows = [...set.base, ...themed].filter(filter);
    if (rows.length === 0) return;
    out.push(
      `## ${title}`,
      "",
      table(
        ["Token", "CSS variable", "Value", "Description"],
        rows.map((t) => [
          code(t.name),
          code(cssVarName(t)),
          code(declarations(t, baseLookup)[0]?.[1] ?? ""),
          t.description ?? "",
        ]),
      ),
      "",
    );
  };
  section("Spacing", (t) => t.path[0] === "spacing" || t.path[0] === "space");
  section("Sizes and breakpoints", (t) => t.path[0] === "size" || t.path[0] === "breakpoint");
  section(
    "Radius and borders",
    (t) => t.path[0] === "radius" || t.path[0] === "border-width" || t.path[0] === "focus",
  );
  section("Shadows and elevation", (t) => t.type === "shadow");
  section("Motion", (t) => t.type === "duration" || t.type === "cubicBezier");
  section("Layering and opacity", (t) => t.path[0] === "z-index" || t.path[0] === "opacity");
  section("Component tokens", (t) => t.layer === "component");

  return `${out.join("\n").trimEnd()}\n`;
}

export function mappingMd(set: TokenSet): string {
  const all = [...set.base, ...(set.themed[set.defaultTheme] ?? [])];
  const rows = all.map((t) => [
    code(t.name),
    code(cssVarName(t)),
    isSemanticColor(t)
      ? code(`*-${tailwindColorName(t)}`)
      : t.type === "typography"
        ? code(`text-${textStyleName(t)}`)
        : "—",
    t.type === "typography"
      ? `Text style ${code(figmaName(t))}`
      : t.type === "shadow"
        ? `Effect style ${code(figmaName(t))}`
        : t.type === "duration" || t.type === "cubicBezier"
          ? "— (code only)"
          : `${t.theme || set.themed[set.defaultTheme]?.includes(t) ? "Theme" : t.layer === "primitive" ? "Primitives" : "Semantic"} / ${code(figmaName(t))}`,
  ]);
  return `${NOTE}
# Token ↔ CSS ↔ Tailwind ↔ Figma mapping

Every name is derived from the token path by the rules in \`packages/tokens/scripts/lib/naming.ts\`:

- **CSS**: semantic colors keep shadcn/ui names (\`color.card.default\` → \`--card\`); everything else is \`--cds-<path>\`; component tokens drop their \`component\` root.
- **Tailwind**: semantic colors map to color utilities (\`bg-card\`, \`text-muted-foreground\`); text styles to \`text-<style>\`; radii to \`rounded-<name>\`; elevations to \`shadow-elevation-<n>\`.
- **Figma**: the token path with \`/\` separators. Colors, numbers and font families become variables; text styles and shadows become styles.

${table(["Token", "CSS variable", "Tailwind", "Figma"], rows)}
`;
}
